import json
import sys

def get_next_step(x, y):
    # Loop coordinates:
    # (4, 51) -> (5, 51) -> (5, 50) -> (4, 50) -> (4, 51)
    if x == 4 and y == 51:
        return ["Right"]
    elif x == 5 and y == 51:
        return ["Up"]
    elif x == 5 and y == 50:
        return ["Left"]
    elif x == 4 and y == 50:
        return ["Down"]
    else:
        # Fallback: navigate towards (4, 51)
        buttons = []
        if x < 4:
            buttons.append("Right")
        elif x > 4:
            buttons.append("Left")
        elif y < 51:
            buttons.append("Down")
        elif y > 51:
            buttons.append("Up")
        return buttons

# Parse input arguments
try:
    # The harness passes arguments as a JSON string in sys.argv[1]
    input_data = json.loads(sys.argv[1]) if len(sys.argv) > 1 else {}
except Exception:
    input_data = {}

# Make sure we cast to int
x = int(input_data.get("x", 4))
y = int(input_data.get("y", 51))

buttons = get_next_step(x, y)
print(json.dumps(buttons))
